INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('cd6cf41a-92fa-54d1-830e-559c17bb64b0','TEXT','The Tiny Ferry','Mia liked helping at the river workshop, especially when there was a small job that nobody had planned. One Friday, Mia noticed the model ferry was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Mia decided to stop and look carefully instead of rushing.
