INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('728bce8f-14c8-52f6-bb1d-92deefa86d61','TEXT','The Orange Tree Calendar','Sienna liked helping at the school orchard, especially when there was a small job that nobody had planned. One Saturday, Sienna noticed the fruit calendar was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Sienna decided to stop and look carefully instead of rushing.
