INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('d82f70d5-cdfb-576e-8dca-dc78b57ef8c8','TEXT','The Creek Sound Map','Noah liked helping at the creek reserve, especially when there was a small job that nobody had planned. One Saturday, Noah noticed the sound map was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Noah decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('9dffe116-c353-5939-8a90-ca38e360800c','TEXT','The Repaired Book — A Different Day','Ruby liked helping at the library corner, especially when there was a small job that nobody had planned. One Thursday, Ruby noticed the repair kit was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Ruby decided to stop and look carefully instead of rushing.
