INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('a6c75b32-ad52-5b62-926e-d63eebc3b89a','TEXT','The Repaired Book','Ruby liked helping at the library corner, especially when there was a small job that nobody had planned. One Saturday, Ruby noticed the repair kit was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Ruby decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('1fc7d9a8-6d01-50d0-9d51-64c26902f8b2','TEXT','The Windy Sculpture — A Different Day','Luca liked helping at the community hall, especially when there was a small job that nobody had planned. One Tuesday, Luca noticed the reed sculpture was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Luca decided to stop and look carefully instead of rushing.
